begin;
create table app.learner_goals(school_id uuid not null,id uuid not null default gen_random_uuid(),learner_id uuid not null,course_id uuid not null,reference_id uuid,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),foreign key(school_id,learner_id)references app.memberships(school_id,actor_id),foreign key(school_id,course_id)references app.courses(school_id,id),foreign key(school_id,reference_id)references app.school_custom_references(school_id,id));
create table app.learner_goal_revisions(school_id uuid not null,id uuid not null default gen_random_uuid(),goal_id uuid not null,revision integer not null check(revision>0),title text not null check(length(btrim(title))between 1 and 200),planned_step text not null check(length(btrim(planned_step))between 1 and 2000),status text not null check(status in('ACTIVE','REVIEWED','CLOSED')),review text,actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,goal_id,revision),foreign key(school_id,goal_id)references app.learner_goals(school_id,id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id),check((status='ACTIVE'and review is null)or(status in('REVIEWED','CLOSED')and length(btrim(review))between 1 and 2000)));
alter table app.learner_goal_revisions add check(status='ACTIVE'or review is not null);
create function internal.learner_goal_allowed(target_school uuid,target_learner uuid,target_course uuid,write_access boolean)returns boolean language sql stable security definer set search_path=''as $$select coalesce(target_school="authorization".school_id()and"authorization".can_access_school(target_school)and"authorization".has_entitlement(target_school,'learner.state')and"authorization".has_entitlement(target_school,'learning')and"authorization".current_learner_course(target_school,target_course,target_learner)and"authorization".can_read_course(target_school,target_course)and internal.learning_published_content(target_school,'course',target_course)is not null and(("authorization".current_role(target_school)='student'and target_learner="authorization".actor_id())or(write_access is false and"authorization".current_role(target_school)in('teacher','admin')and"authorization".can_manage_course(target_school,target_course)and"authorization".can_view_person(target_school,target_learner))),false)$$;
create function internal.learner_goal_projection(target_goal uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();goal app.learner_goals;revision app.learner_goal_revisions;begin
 select*into goal from app.learner_goals where school_id=school and id=target_goal;if not found or not internal.learner_goal_allowed(school,goal.learner_id,goal.course_id,false)then raise exception 'Goal source denied'using errcode='42501';end if;
  select r.*into revision from app.learner_goal_revisions r where r.school_id=school and r.goal_id=goal.id order by r.revision desc limit 1;
 return jsonb_build_object('id',goal.id,'revisionId',revision.id,'revision',revision.revision,'learnerId',goal.learner_id,'learnerName',(select p.display_name from app.people p where p.school_id=school and p.actor_id=goal.learner_id),'courseId',goal.course_id,'courseTitle',internal.learning_published_content(school,'course',goal.course_id)->>'title','referenceId',goal.reference_id,'referenceTitle',(select r.title from app.school_custom_references r where r.school_id=school and r.id=goal.reference_id),'title',revision.title,'plannedStep',revision.planned_step,'status',revision.status,'review',revision.review,'createdAt',goal.created_at,'reviewedAt',case when revision.status='ACTIVE'then null else revision.created_at end);
end$$;
create function internal.learner_goal_command(command_name text,target_goal uuid,payload jsonb,command_key text,fingerprint text,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();goal app.learner_goals;current_revision app.learner_goal_revisions;course uuid;reservation jsonb;goal_id uuid;revision_id uuid;begin
 perform internal.require_context();if payload is null or jsonb_typeof(payload)<>'object'or command_name is null or command_name not in('create','review')then raise exception 'Goal command invalid'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(school::text||':school-access-mutations',0));
 if command_name='create'then if not(payload?&array['courseId','referenceId','title','plannedStep'])or jsonb_typeof(payload->'courseId')is distinct from'string'or not(jsonb_typeof(payload->'referenceId')in('string','null'))then raise exception 'Explicit goal source required'using errcode='22023';end if;course:=(payload->>'courseId')::uuid;if target_goal is not null or payload-array['courseId','referenceId','title','plannedStep']<>'{}'::jsonb or jsonb_typeof(payload->'title')is distinct from'string'or jsonb_typeof(payload->'plannedStep')is distinct from'string'or length(btrim(payload->>'title'))not between 1 and 200 or length(btrim(payload->>'plannedStep'))not between 1 and 2000 then raise exception 'Explicit learner goal required'using errcode='22023';end if;
 else select g.*into goal from app.learner_goals g where g.school_id=school and g.id=target_goal;course:=goal.course_id;if goal.id is null or goal.learner_id is distinct from actor then raise exception 'Own goal required'using errcode='42501';end if;end if;
 if not internal.learner_goal_allowed(school,actor,course,true)then raise exception 'Current own goal course required'using errcode='42501';end if;
 perform internal.require_curriculum_academic_write(course);
 perform 1 from app.memberships member where member.school_id=school and member.actor_id=actor for share;
 perform 1 from app.enrollments enrollment join app.courses selected on selected.school_id=enrollment.school_id and selected.class_id=enrollment.class_id where selected.school_id=school and selected.id=course and enrollment.student_actor_id=actor for share of enrollment;
 if not internal.learner_goal_allowed(school,actor,course,true)then raise exception 'Goal source access changed'using errcode='42501';end if;
 if command_name='review'then select g.*into goal from app.learner_goals g where g.school_id=school and g.id=target_goal for update;end if;
 if command_name='create'and payload->>'referenceId'is not null and not exists(select 1 from app.school_custom_references reference where reference.school_id=school and reference.id=(payload->>'referenceId')::uuid and reference.status='APPROVED'and(not exists(select 1 from app.programme_course_contexts pinned where pinned.school_id=school and pinned.course_id=course)or exists(select 1 from app.course_objective_approvals approval where approval.school_id=school and approval.course_id=course and approval.academic_reference_id=reference.id)))then raise exception 'Approved goal objective required'using errcode='22023';end if;
 reservation:=internal.begin_command(command_key,'learner.goal.'||command_name,fingerprint);if reservation->>'state'='COMPLETED'then return internal.learner_goal_projection((reservation->'response'->>'id')::uuid);elsif reservation->>'state'<>'NEW'then raise exception 'Goal command pending'using errcode='22023';end if;
 if command_name='create'then insert into app.learner_goals(school_id,learner_id,course_id,reference_id)values(school,actor,course,(payload->>'referenceId')::uuid)returning id into goal_id;insert into app.learner_goal_revisions(school_id,goal_id,revision,title,planned_step,status,actor_id)values(school,goal_id,1,payload->>'title',payload->>'plannedStep','ACTIVE',actor)returning id into revision_id;
 else select r.*into current_revision from app.learner_goal_revisions r where r.school_id=school and r.goal_id=goal.id order by r.revision desc limit 1;
  if payload-array['expectedRevision','status','review','confirmReview']<>'{}'::jsonb or payload->'confirmReview'is distinct from'true'::jsonb or jsonb_typeof(payload->'expectedRevision')is distinct from'number'or current_revision.revision::numeric is distinct from(payload->>'expectedRevision')::numeric or current_revision.status='CLOSED'or payload->>'status'is null or payload->>'status'not in('REVIEWED','CLOSED')or jsonb_typeof(payload->'review')is distinct from'string'or length(btrim(payload->>'review'))not between 1 and 2000 then raise exception 'Current explicit goal review required'using errcode='22023';end if;
  goal_id:=goal.id;insert into app.learner_goal_revisions(school_id,goal_id,revision,title,planned_step,status,review,actor_id)values(school,goal_id,current_revision.revision+1,current_revision.title,current_revision.planned_step,payload->>'status',payload->>'review',actor)returning id into revision_id;
 end if;
 perform internal.append_audit('learner.goal.'||command_name,'learner_goal',goal_id,request_id,'succeeded',jsonb_build_object('revisionId',revision_id));perform internal.enqueue_event('learner.goal.recorded','learner_goal_revision',revision_id,1,'{}','learner-goal:'||revision_id::text);perform internal.finish_command(command_key,'learner.goal.'||command_name,fingerprint,jsonb_build_object('id',goal_id));return internal.learner_goal_projection(goal_id);
end$$;
create function internal.read_learner_goals(target_learner uuid,page_limit integer,page_cursor uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();learner uuid:=coalesce(target_learner,"authorization".actor_id());items jsonb;begin
 if not"authorization".can_access_school(school)or not"authorization".has_entitlement(school,'learner.state')or"authorization".current_role(school)is null or"authorization".current_role(school)not in('student','teacher','admin')or"authorization".current_role(school)='student'and learner<>"authorization".actor_id()or not"authorization".can_view_person(school,learner)then raise exception 'Goal learner scope denied'using errcode='42501';end if;
 if page_limit is null or page_limit not between 1 and 25 then raise exception 'Bounded goals required'using errcode='22023';end if;
 select coalesce(jsonb_agg(internal.learner_goal_projection(g.id)order by g.id),'[]'::jsonb)into items from(select g.id from app.learner_goals g where g.school_id=school and g.learner_id=learner and(page_cursor is null or g.id>page_cursor)and internal.learner_goal_allowed(school,g.learner_id,g.course_id,false)order by g.id limit page_limit+1)g;
 if octet_length(items::text)>500000 then raise exception 'Smaller goal page required'using errcode='22023';end if;
 return jsonb_build_object('items',case when jsonb_array_length(items)>page_limit then items-page_limit else items end,'nextCursor',case when jsonb_array_length(items)>page_limit then items->(page_limit-1)->>'id'else null end);
end$$;
do $$declare tab text;begin foreach tab in array array['learner_goals','learner_goal_revisions']loop execute format('alter table app.%I enable row level security',tab);execute format('alter table app.%I force row level security',tab);execute format('revoke all on app.%I from public,anon,authenticated,service_role,cuevo_api,cuevo_worker',tab);execute format('create trigger goal_immutable before update or delete on app.%I for each row execute function internal.academic_history_immutable()',tab);execute format('create trigger goal_no_truncate before truncate on app.%I for each statement execute function internal.academic_history_immutable()',tab);end loop;end$$;
do $$declare definition text;anchor text;begin definition:=pg_get_functiondef('internal.process_learner_event(uuid,uuid)'::regprocedure);anchor:='begin'||chr(10);if position(anchor in definition)=0 then raise exception 'Goal dispatcher changed'using errcode='22023';end if;definition:=replace(definition,anchor,'begin'||chr(10)||'if exists(select 1 from internal.outbox_events event where event.id=target_event and event.type=''learner.goal.recorded'')then select*into e from internal.outbox_events where id=target_event for update;if e.state<>''PROCESSING''or e.lease_token is distinct from current_lease or e.lease_until<=clock_timestamp()or e.version<>1 or e.entity_type<>''learner_goal_revision''or not exists(select 1 from app.learner_goal_revisions source where source.school_id=e.school_id and source.id=e.entity_id and source.actor_id=e.actor_id)then raise exception ''Goal event source invalid''using errcode=''22023'';end if;insert into internal.processed_events(event_id,school_id)values(e.id,e.school_id)on conflict(event_id)do nothing;if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception ''Goal event lease changed''using errcode=''22023'';end if;return jsonb_build_object(''status'',''ACKNOWLEDGED'');end if;'||chr(10));execute definition;end$$;
revoke execute on function internal.learner_goal_allowed(uuid,uuid,uuid,boolean),internal.learner_goal_projection(uuid),internal.learner_goal_command(text,uuid,jsonb,text,text,text),internal.read_learner_goals(uuid,integer,uuid)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.learner_goal_command(text,uuid,jsonb,text,text,text),internal.read_learner_goals(uuid,integer,uuid)to cuevo_api;
commit;
